{"title": "Rollback depth distribution", "type": "vega", "aggs": [], "params": {"spec": "{
 "title": "How deep are the corrections",
 "data": {
  "url": {
   "index": "rollback-events",
   "body": {
    "size": 0,
    "query": {
     "term": {
      "event": "rolled_back"
     }
    },
    "aggs": {
     "sessions": {
      "terms": {
       "field": "mode",
       "size": 12
      },
      "aggs": {
       "d": {
        "terms": {
         "field": "depth",
         "size": 20,
         "order": {
          "_key": "asc"
         }
        }
       }
      }
     }
    }
   }
  },
  "format": {
   "property": "aggregations.sessions.buckets"
  }
 },
 "transform": [
  {
   "flatten": [
    "d.buckets"
   ],
   "as": [
    "b"
   ]
  },
  {
   "calculate": "datum.b.key",
   "as": "depth"
  },
  {
   "calculate": "datum.b.doc_count",
   "as": "count"
  },
  {
   "calculate": "datum.key",
   "as": "mode"
  }
 ],
 "mark": {
  "type": "bar",
  "tooltip": true
 },
 "encoding": {
  "x": {
   "field": "depth",
   "type": "ordinal",
   "title": "rollback depth (frames)"
  },
  "y": {
   "field": "count",
   "type": "quantitative",
   "title": "corrections",
   "stack": null
  },
  "color": {
   "field": "mode",
   "type": "nominal",
   "title": "mode"
  },
  "xOffset": {
   "field": "mode",
   "type": "nominal"
  }
 },
