{"title": "Prediction accuracy holds everywhere", "type": "vega", "aggs": [], "params": {"spec": "{
 "title": "Prediction accuracy",
 "data": {
  "url": {
   "index": "rollback-metrics",
   "body": {
    "size": 0,
    "aggs": {
     "sessions": {
      "terms": {
       "field": "session",
       "size": 60
      },
      "aggs": {
       "mode": {
        "terms": {
         "field": "mode",
         "size": 1
        }
       },
       "simulation": {
        "terms": {
         "field": "simulation",
         "size": 1
        }
       },
       "player": {
        "terms": {
         "field": "player",
         "size": 1
        }
       },
       "pred": {
        "max": {
         "field": "local.predicted_frames"
        }
       },
       "miss": {
        "max": {
         "field": "local.mispredicted_frames"
        }
       }
      }
     }
    }
   }
  },
  "format": {
   "property": "aggregations.sessions.buckets"
  }
 },
 "transform": [
  {
   "calculate": "datum.mode.buckets[0] ? datum.mode.buckets[0].key : 'unknown'",
   "as": "mode"
  },
  {
   "calculate": "datum.simulation.buckets[0] ? datum.simulation.buckets[0].key : '?'",
   "as": "sim"
  },
  {
   "calculate": "datum.player.buckets[0] ? datum.player.buckets[0].key : '?'",
   "as": "player"
  },
  {
   "calculate": "datum.mode + '  \u00b7  ' + datum.sim + '  \u00b7  ' + datum.player",
   "as": "label"
  },
  {
   "calculate": "datum['pred'].value",
   "as": "pred"
  },
  {
   "calculate": "datum['miss'].value",
   "as": "miss"
  },
  {
   "filter": "datum.pred > 0"
  },
  {
   "calculate": "100 * (1 - datum.miss / datum.pred)",
   "as": "accuracy"
  }
 ],
 "mark": {
  "type": "bar",
  "tooltip": true
 },
 "encoding": {
  "y": {
   "field": "label",
   "type": "nominal",
   "title": null,
   "sort": {
    "field": "accuracy",
    "op": "max",
    "order": "descending"
   },
   "axis": {
    "labelFontSize": 12,
    "labelLimit": 260
   }
  },
  "x": {
   "field": "accuracy",
   "type": "quantitative",
   "title": "accuracy (%)",
   "scale": {
    "domain": [
     85,
     100
    ]
   }
  },
  "x2": {
   "datum": 85
  },
  "color": {
   "field": "mode",
   "type": "nominal",
   "title": "run"
  },
  "tooltip": [
   {
    "field": "label",
    "type": "nominal",
    "title": "run"
   },
   {
    "field": "accuracy",
    "type": "quantitative",
    "format": ".1f"
   }
  ]
 },
 "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
 "config": {
  "kibana": {
   "renderer": "svg"
  }
 }
}"}}

