  }
 },
 "transform": [
  {
   "calculate": "datum.mode.buckets[0] ? datum.mode.buckets[0].key : 'unknown'",
   "as": "mode"
  },
  {
   "calculate": "datum.simulation.buckets[0] ? datum.simulation.buckets[0].key : '?'",
   "as": "sim"
  },
  {
   "calculate": "datum.player.buckets[0] ? datum.player.buckets[0].key : '?'",
   "as": "player"
  },
  {
   "calculate": "datum.mode + '  \u00b7  ' + datum.sim + '  \u00b7  ' + datum.player",
   "as": "label"
  },
  {
   "calculate": "datum['advance'].value",
   "as": "advance"
  },
  {
   "calculate": "datum['save'].value",
   "as": "save"
  },
  {
   "calculate": "datum['presented'].value",
   "as": "presented"
  },
  {
   "calculate": "datum['resim'].value",
   "as": "resim"
  },
  {
   "calculate": "datum.presented + datum.resim",
   "as": "simulated"
  },
  {
   "filter": "datum.simulated > 0"
  },
  {
   "calculate": "datum.advance / 1000 / datum.simulated",
