  },
  {
   "calculate": "datum.save / 1000 / datum.simulated",
   "as": "save_us"
  },
  {
   "fold": [
    "advance_us",
    "save_us"
   ],
   "as": [
    "phase",
    "us"
   ]
  }
 ],
 "mark": {
  "type": "bar",
  "tooltip": true
 },
 "encoding": {
  "y": {
   "field": "label",
   "type": "nominal",
   "title": null
  },
  "x": {
   "field": "us",
   "type": "quantitative",
   "title": "microseconds per simulated frame"
  },
  "color": {
   "field": "phase",
   "type": "nominal",
   "title": null
  }
 },
 "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
 "config": {
  "kibana": {
   "renderer": "svg"
  }
 }
}"}}

